$ErrorActionPreference = 'Stop'; [Console]::OutputEncoding = New-Object System.Text.UTF8Encoding; Add-Type -AssemblyName System.Windows.Forms; Add-Type -AssemblyName System.Drawing; $owner = New-Object System.Windows.Forms.Form; $owner.TopMost = $true; $owner.StartPosition = 'Manual'; $owner.Location = New-Object System.Drawing.Point(-3000, -3000); $owner.Size = New-Object System.Drawing.Size(1, 1); $dialog = New-Object System.Windows.Forms.OpenFileDialog; $dialog.Title = '选择目录'; if (Test-Path -LiteralPath $env:CHATAGENT_PICKER_INITIAL -PathType Container) { $dialog.InitialDirectory = $env:CHATAGENT_PICKER_INITIAL }; $dialog.CheckFileExists = $false; $dialog.CheckPathExists = $true; $dialog.AddExtension = $false; $dialog.ValidateNames = $false; $dialog.Multiselect = $false; $dialog.RestoreDirectory = $true; $dialog.FileName = '选择此目录'; $dialog.Filter = '目录|*.directory'; if ($dialog.ShowDialog($owner) -eq [System.Windows.Forms.DialogResult]::OK) { $p = Split-Path -Parent $dialog.FileName; if ($p) { [Console]::Write($p) } }; $owner.Dispose()